import { PrismaClient } from "@prisma/client";

const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };

export const db = globalForPrisma.prisma ?? new PrismaClient();

if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = db;
---AUTH---
import { SignJWT, jwtVerify } from "jose";
import { cookies } from "next/headers";
import { cache } from "react";
import { db } from "./db";
import type { User } from "@prisma/client";

const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";

export async function createSession(userId: string) {
  const token = await new SignJWT({ sub: userId })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("7d")
    .sign(secret);
  const jar = await cookies();
  jar.set(COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1",
    maxAge: 60 * 60 * 24 * 7,
    path: "/",
  });
}

export async function destroySession() {
  const jar = await cookies();
  jar.delete(COOKIE);
}

const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;

/** The real signed-in account, ignoring any impersonation. */
export const realUser = cache(async (): Promise<User | null> => {
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, secret);
    if (!payload.sub) return null;
    const user = await db.user.findUnique({ where: { id: payload.sub } });
    if (!user || user.suspended) return null;
    return user;
  } catch {
    return null;
  }
});

/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
export const currentUser = cache(async (): Promise<User | null> => {
  const real = await realUser();
  if (!real) return null;
  if (real.role === "ADMIN") {
    const jar = await cookies();
    const imp = jar.get(IMP_COOKIE)?.value;
    if (imp) {
      try {
        const { payload } = await jwtVerify(imp, secret);
        if (payload.adminId === real.id && typeof payload.sub === "string") {
          const target = await db.user.findUnique({ where: { id: payload.sub } });
          if (target) return target;
        }
      } catch {
        /* expired/invalid impersonation — fall through to real user */
      }
    }
  }
  return real;
});

/** Non-null when the current request is an admin impersonating a customer. */
export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") return null;
  const target = await currentUser();
  if (!target || target.id === real.id) return null;
  return { admin: real, target };
});

export async function setImpersonation(targetUserId: string) {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
  const token = await new SignJWT({ sub: targetUserId, adminId: real.id })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("2h")
    .sign(secret);
  const jar = await cookies();
  jar.set(IMP_COOKIE, token, { httpOnly: true, sameSite: "lax", path: "/", maxAge: 7200 });
}

export async function clearImpersonation() {
  const jar = await cookies();
  jar.delete(IMP_COOKIE);
}

export async function requireUser(): Promise<User> {
  const user = await currentUser();
  if (!user) throw new Error("UNAUTHORIZED");
  return user;
}

export async function requireAdmin(): Promise<User> {
  const user = await requireUser();
  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
  return user;
}

/**
 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
 * per-area gating lives in lib/rbac.ts (`requireArea`).
 */
export async function requireStaff(): Promise<User> {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
    throw new Error("FORBIDDEN");
  }
  return user;
}
---RBAC---
import { redirect } from "next/navigation";
import type { Role, User } from "@prisma/client";
import { realUser } from "./auth";

/**
 * Role-based access control for the admin ops portal.
 *
 * The admin surface is divided into logical *areas*. Each area maps to the set
 * of staff roles allowed to see and use it. ADMIN implicitly has every area.
 * The admin layout uses this to (a) let any staff role in and (b) hide nav
 * items a role can't reach; each sensitive page additionally gates itself with
 * `requireArea(...)` so a hand-typed URL is refused too.
 */
export type Area =
  | "overview"
  | "analytics"
  | "clients"
  | "support"
  | "fleet"
  | "billing"
  | "platform";

/** Which roles may access each area. ADMIN is always allowed (see canAccess). */
export const AREA_ROLES: Record<Area, Role[]> = {
  overview: ["SUPPORT", "BILLING", "ADMIN"],
  analytics: ["ADMIN"],
  clients: ["SUPPORT", "ADMIN"],
  support: ["SUPPORT", "ADMIN"],
  fleet: ["ADMIN"],
  billing: ["BILLING", "ADMIN"],
  platform: ["ADMIN"],
};

export function canAccess(role: Role, area: Area): boolean {
  return role === "ADMIN" || AREA_ROLES[area].includes(role);
}

/** Any non-customer role that belongs in the ops portal. */
export function isStaff(role: Role): boolean {
  return role === "SUPPORT" || role === "BILLING" || role === "ADMIN";
}

/** Maps admin nav hrefs to their governing area. Unknown routes default to platform (ADMIN-only). */
const HREF_AREA: Record<string, Area> = {
  "/admin": "overview",
  "/admin/analytics": "analytics",
  "/admin/users": "clients",
  "/admin/support": "support",
  "/admin/servers": "fleet",
  "/admin/nodes": "fleet",
  "/admin/ips": "fleet",
  "/admin/provisioning": "fleet",
  "/admin/monitoring": "fleet",
  "/admin/infrastructure": "fleet",
  "/admin/subscriptions": "billing",
  "/admin/billing": "billing",
  "/admin/invoices": "billing",
  "/admin/plans": "billing",
  "/admin/coupons": "billing",
  "/admin/game-plans": "billing",
  "/admin/feedback": "support",
  "/admin/logs": "platform",
  "/admin/domains": "platform",
  "/admin/grant": "platform",
  "/admin/audit": "platform",
  "/admin/automation": "platform",
  "/admin/settings": "platform",
  "/admin/staff": "platform",
  "/admin/email-templates": "platform",
  "/admin/games": "platform",
  "/admin/blog": "platform",
};

export function areaForHref(href: string): Area {
  return HREF_AREA[href] ?? "platform";
}

export function canAccessHref(role: Role, href: string): boolean {
  return canAccess(role, areaForHref(href));
}

/**
 * Server-side page guard. Redirects to /login if signed out, or back to the
 * overview if the (staff) user's role can't reach this area. Returns the real
 * signed-in user (impersonation is refused elsewhere in the admin layout).
 */
export async function requireArea(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) redirect("/login");
  if (!isStaff(user.role)) redirect("/dashboard");
  if (!canAccess(user.role, area)) redirect("/admin");
  return user;
}

===PRIMITIVES===
import Link from "next/link";
import { Sparkline } from "./charts";

export function PageHeader({
  title,
  sub,
  children,
}: {
  title: string;
  sub?: string;
  children?: React.ReactNode;
}) {
  return (
    <div className="mb-6 flex flex-wrap items-end justify-between gap-4">
      <div>
        <h1 className="page-title">{title}</h1>
        {sub && <p className="mt-1 text-sm text-slate-400">{sub}</p>}
      </div>
      {children && <div className="flex items-center gap-2">{children}</div>}
    </div>
  );
}

export function StatCard({
  label,
  value,
  delta,
  deltaGood,
  spark,
  sparkColor = "#8a70fb",
  icon,
  href,
}: {
  label: string;
  value: string;
  delta?: string;
  deltaGood?: boolean;
  spark?: number[];
  sparkColor?: string;
  icon?: React.ReactNode;
  href?: string;
}) {
  const inner = (
    <div className="card card-hover flex h-full flex-col justify-between p-5">
      <div className="flex items-start justify-between">
        <div>
          <p className="text-[13px] text-slate-400">{label}</p>
          <p className="mt-1.5 text-2xl font-bold tracking-tight">{value}</p>
          {delta && (
            <p className={`mt-1 text-xs font-medium ${deltaGood === false ? "text-red-400" : "text-emerald-400"}`}>
              {delta}
            </p>
          )}
        </div>
        {icon && (
          <div className="rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-2.5 text-brand-300">
            {icon}
          </div>
        )}
      </div>
      {spark && spark.length > 1 && (
        <div className="mt-3">
          <Sparkline data={spark} width={200} height={32} stroke={sparkColor} id={label.replace(/\W/g, "")} />
        </div>
      )}
    </div>
  );
  return href ? <Link href={href}>{inner}</Link> : inner;
}

const statusColors: Record<string, { dot: string; text: string; pulse?: boolean }> = {
  RUNNING: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  online: { dot: "bg-emerald-400", text: "text-emerald-400", pulse: true },
  STOPPED: { dot: "bg-slate-500", text: "text-slate-400" },
  PENDING: { dot: "bg-amber-400", text: "text-amber-400" },
  PROVISIONING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
  REINSTALLING: { dot: "bg-amber-400", text: "text-amber-400", pulse: true },
  DELETING: { dot: "bg-red-400", text: "text-red-400", pulse: true },
  SUSPENDED: { dot: "bg-red-400", text: "text-red-400" },
  ERROR: { dot: "bg-red-400", text: "text-red-400" },
  QUEUED: { dot: "bg-amber-400", text: "text-amber-400" },
  DONE: { dot: "bg-emerald-400", text: "text-emerald-400" },
  FAILED: { dot: "bg-red-400", text: "text-red-400" },
  OPEN: { dot: "bg-amber-400", text: "text-amber-400" },
  ANSWERED: { dot: "bg-brand-300", text: "text-brand-300" },
  CUSTOMER_REPLY: { dot: "bg-amber-400", text: "text-amber-400" },
  CLOSED: { dot: "bg-slate-500", text: "text-slate-400" },
};

export function StatusDot({ status, label }: { status: string; label?: string }) {
  const s = statusColors[status] ?? statusColors.STOPPED;
  return (
    <span className={`inline-flex items-center gap-2 text-xs font-medium ${s.text}`}>
      <span className={`h-2 w-2 rounded-full ${s.dot} ${s.pulse ? "animate-pulse-dot" : ""}`} />
      {(label ?? status).toLowerCase().replace(/_/g, " ")}
    </span>
  );
}

export function Badge({
  children,
  tone = "brand",
}: {
  children: React.ReactNode;
  tone?: "brand" | "green" | "red" | "amber" | "slate";
}) {
  const tones = {
    brand: "border-brand-500/40 bg-brand-500/10 text-brand-300",
    green: "border-emerald-500/40 bg-emerald-500/10 text-emerald-300",
    red: "border-red-500/40 bg-red-500/10 text-red-300",
    amber: "border-amber-500/40 bg-amber-500/10 text-amber-300",
    slate: "border-white/10 bg-white/[0.05] text-slate-400",
  };
  return (
    <span className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${tones[tone]}`}>
      {children}
    </span>
  );
}

===BILLING PAGE===
import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, fmtMoney, fmtBytes, timeAgo } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { AddFunds } from "@/components/customer/AddFunds";
import { CouponField } from "@/components/customer/CouponField";
import { InvoiceStatusBadge, DownloadInvoiceButton } from "@/components/customer/InvoiceViews";

export const dynamic = "force-dynamic";

export default async function BillingPage({
  searchParams,
}: {
  searchParams: Promise<{ paid?: string; canceled?: string }>;
}) {
  const { paid, canceled } = await searchParams;
  const user = await requireUser();
  const [transactions, paidServers, bwServers, invoices] = await Promise.all([
    db.walletTransaction.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 60,
    }),
    db.server.findMany({
      where: { userId: user.id, isFree: false, status: { not: "DELETING" } },
      include: { plan: true },
      orderBy: { expiresAt: "asc" },
    }),
    db.server.findMany({
      where: { userId: user.id, status: { not: "DELETING" } },
      include: { plan: true },
      orderBy: { createdAt: "asc" },
    }),
    db.invoice.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
      take: 5,
    }),
  ]);

  const monthlySpendCents = paidServers.reduce((sum, s) => sum + s.plan.priceCents, 0);
  const upcoming = paidServers.filter((s) => s.expiresAt !== null);

  // Bandwidth usage: (bwIn + bwOut) vs plan allowance (bandwidthTB * 1e12 bytes).
  const bandwidth = bwServers.map((s) => {
    const usedBytes = Number(s.bwInBytes) + Number(s.bwOutBytes);
    const allowanceBytes = s.plan.bandwidthTB * 1e12;
    const pct = allowanceBytes > 0 ? (usedBytes / allowanceBytes) * 100 : 0;
    return { server: s, usedBytes, allowanceBytes, pct };
  });
  const totalUsedBytes = bandwidth.reduce((sum, b) => sum + b.usedBytes, 0);
  const totalAllowanceBytes = bandwidth.reduce((sum, b) => sum + b.allowanceBytes, 0);
  const totalPct = totalAllowanceBytes > 0 ? (totalUsedBytes / totalAllowanceBytes) * 100 : 0;
  const meterColor = (pct: number) => (pct > 100 ? "#ef4444" : pct > 80 ? "#f59e0b" : "#6f47f5");
  const pctTone = (pct: number) =>
    pct > 100 ? "text-red-400" : pct > 80 ? "text-amber-400" : "text-slate-400";

  return (
    <div className="space-y-6">
      <PageHeader title="Billing" sub="Wallet, renewals and transaction history." />

      {paid === "1" && (
        <div className="card border-emerald-500/30 bg-emerald-500/[0.06] text-sm text-emerald-300">
          Payment received — your balance updates within seconds. Refresh if you don&apos;t see it
          yet.
        </div>
      )}
      {canceled === "1" && (
        <div className="card border-amber-500/30 bg-amber-500/[0.06] text-sm text-amber-300">
          Checkout canceled — no charge was made.
        </div>
      )}

      <div className="card relative overflow-hidden">
        <div
          className="pointer-events-none absolute inset-0"
          style={{
            background:
              "linear-gradient(120deg, rgb(59 130 246 / 0.12), rgb(111 71 245 / 0.14) 55%, transparent)",
          }}
        />
        <div className="relative flex flex-wrap items-end justify-between gap-6">
          <div>
            <p className="text-sm text-slate-400">Wallet balance</p>
            <p className="mt-1 text-4xl font-bold tracking-tight">
              <span className="grad-text">{fmtMoney(user.balanceCents)}</span>
            </p>
            <p className="mt-2 text-xs text-slate-500">
              Servers renew and domains register straight from this balance.
            </p>
          </div>
          <AddFunds />
        </div>
        <div className="relative mt-5 border-t border-white/[0.06] pt-4">
          <CouponField />
        </div>
      </div>

      <Link
        href="/dashboard/refer"
        className="card card-hover flex flex-wrap items-center justify-between gap-3 border-brand-500/30 bg-brand-500/[0.05]"
      >
        <div>
          <p className="font-semibold text-brand-200">Refer a friend, earn credit</p>
          <p className="mt-0.5 text-sm text-slate-400">
            You both get wallet credit when they make their first payment.
          </p>
        </div>
        <span className="btn-secondary py-1.5">Get your link</span>
      </Link>

      <div className="grid gap-6 lg:grid-cols-[340px_1fr]">
        <div className="space-y-6">
          <div className="card">
            <p className="section-label mb-3">Monthly spend</p>
            <p className="text-2xl font-bold">{fmtMoney(monthlySpendCents)}<span className="text-sm font-normal text-slate-400">/mo</span></p>
            <p className="mt-1 text-xs text-slate-500">
              {paidServers.length} paid server{paidServers.length === 1 ? "" : "s"} across your
              account.
            </p>
          </div>

          <div className="card">
            <p className="section-label mb-3">Upcoming renewals</p>
            {upcoming.length === 0 ? (
              <p className="text-sm text-slate-400">No renewals scheduled.</p>
            ) : (
              <ul className="space-y-3">
                {upcoming.map((s) => (
                  <li key={s.id} className="flex items-center justify-between gap-3 text-sm">
                    <Link
                      href={`/dashboard/servers/${s.id}`}
                      className="min-w-0 flex-1 truncate font-medium hover:text-brand-300"
                    >
                      {s.hostname}
                    </Link>
                    <span className="shrink-0 text-xs text-slate-400">
                      {s.expiresAt!.toISOString().slice(0, 10)}
                    </span>
                    <span className="shrink-0 font-mono text-xs text-slate-300">
                      {fmtMoney(s.plan.priceCents)}
                    </span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>

        <div className="card overflow-x-auto p-0">
          <p className="section-label px-4 pt-4">Transactions</p>
          {transactions.length === 0 ? (
            <p className="px-4 py-8 text-sm text-slate-400">
              No transactions yet — your invoices and top-ups will appear here.
            </p>
          ) : (
            <table className="table-shell mt-2 min-w-[520px]">
              <thead>
                <tr>
                  <th>Description</th>
                  <th className="text-right">Amount</th>
                  <th className="text-right">Date</th>
                </tr>
              </thead>
              <tbody>
                {transactions.map((t) => (
                  <tr key={t.id}>
                    <td>{t.description}</td>
                    <td
                      className={`text-right font-mono ${
                        t.amountCents < 0 ? "text-red-400" : "text-emerald-400"
                      }`}
                    >
                      {t.amountCents < 0 ? "−" : "+"}
                      {fmtMoney(Math.abs(t.amountCents))}
                    </td>
                    <td className="text-right text-slate-400" title={t.createdAt.toISOString()}>
                      {timeAgo(t.createdAt)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>

      {/* Bandwidth usage */}
      <div className="card">
        <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
          <div>
            <p className="section-label">Bandwidth usage</p>
            <p className="mt-1 text-sm text-slate-400">
              Transfer used this cycle across your servers versus plan allowance.
            </p>
          </div>
          <div className="text-right">
            <p className={`text-lg font-bold ${pctTone(totalPct)}`}>
              {fmtBytes(totalUsedBytes)}
              <span className="text-sm font-normal text-slate-500">
                {" "}
                / {totalAllowanceBytes > 0 ? fmtBytes(totalAllowanceBytes) : "—"}
              </span>
            </p>
            <p className="text-xs text-slate-500">{totalPct.toFixed(0)}% of total allowance</p>
          </div>
        </div>
        {bandwidth.length === 0 ? (
          <p className="text-sm text-slate-400">No active servers.</p>
        ) : (
          <ul className="space-y-4">
            {bandwidth.map(({ server: s, usedBytes, allowanceBytes, pct }) => (
              <li key={s.id}>
                <div className="mb-1.5 flex items-center justify-between gap-3 text-sm">
                  <Link
                    href={`/dashboard/servers/${s.id}`}
                    className="min-w-0 flex-1 truncate font-medium hover:text-brand-300"
                  >
                    {s.hostname}
                    <span className="ml-2 text-xs font-normal text-slate-500">{s.plan.name}</span>
                  </Link>
                  <span className={`shrink-0 font-mono text-xs ${pctTone(pct)}`}>
                    {fmtBytes(usedBytes)} / {fmtBytes(allowanceBytes)}
                  </span>
                </div>
                <MeterBar value={usedBytes} max={allowanceBytes} color={meterColor(pct)} />
                {pct > 100 && (
                  <p className="mt-1 text-xs text-red-400">
                    Over allowance by {fmtBytes(usedBytes - allowanceBytes)} — overage may apply.
                  </p>
                )}
                {pct > 80 && pct <= 100 && (
                  <p className="mt-1 text-xs text-amber-400">
                    {pct.toFixed(0)}% used — approaching your plan limit.
                  </p>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>

      {/* Invoices */}
      <div className="card p-0">
        <div className="flex items-center justify-between gap-3 px-5 pt-5">
          <div>
            <p className="section-label">Invoices</p>
            <p className="mt-1 text-xs text-slate-500">Your most recent billing documents.</p>
          </div>
          <Link href="/dashboard/invoices" className="btn-secondary py-1.5">
            View all
          </Link>
        </div>
        {invoices.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-400">
            No invoices yet — they appear here once issued for paid services.
          </p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell min-w-[560px]">
              <thead>
                <tr>
                  <th>Number</th>
                  <th>Description</th>
                  <th>Status</th>
                  <th className="text-right">Amount</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {invoices.map((inv) => (
                  <tr key={inv.id}>
                    <td className="font-mono text-xs text-slate-300">
                      <Link href={`/dashboard/invoices/${inv.id}`} className="hover:text-brand-300">
                        #{String(inv.number).padStart(5, "0")}
                      </Link>
                    </td>
                    <td className="max-w-xs truncate">
                      <Link href={`/dashboard/invoices/${inv.id}`} className="hover:text-brand-300">
                        {inv.description}
                      </Link>
                    </td>
                    <td>
                      <InvoiceStatusBadge status={inv.status} />
                    </td>
                    <td className="text-right font-mono">{fmtMoney(inv.amountCents)}</td>
                    <td className="text-right">
                      <DownloadInvoiceButton id={inv.id} label="Download" className="btn-ghost py-1 text-xs" />
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

