export async function adminCreateCoupon(
  prev: any,
  formData: FormData
): Promise<{ error?: string; ok?: boolean }> {
  const admin = await requireAdmin();
  const rawExpires = String(formData.get("expiresAt") ?? "").trim();
  const rawMin = String(formData.get("minAmountCents") ?? "").trim();
  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
  const parsed = couponSchema.safeParse({
    code: formData.get("code"),
    kind: formData.get("kind"),
    scope: formData.get("scope"),
    value: formData.get("value"),
    firstTimeOnly: formData.get("firstTimeOnly") === "on",
    minAmountCents: rawMin === "" ? undefined : rawMin,
    maxRedemptions: rawMax === "" ? undefined : rawMax,
    expiresAt: rawExpires === "" ? undefined : rawExpires,
    note: formData.get("note") || undefined,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
  }
  const data = parsed.data;
  if (data.kind === "PERCENT" && data.value > 100) {
    return { error: "Percent value must be between 1 and 100." };
  }
  const code = data.code.toUpperCase();

  const existing = await db.coupon.findUnique({ where: { code } });
  if (existing) return { error: "A coupon with that code already exists." };

  let expiresAt: Date | null = null;
  if (data.expiresAt) {
    const d = new Date(data.expiresAt);
    if (Number.isNaN(d.getTime())) return { error: "Invalid expiry date." };
    expiresAt = d;
  }

  await db.coupon.create({
    data: {
      code,
      kind: data.kind,
      scope: data.scope,
      value: data.value,
      firstTimeOnly: data.firstTimeOnly,
      minAmountCents: data.minAmountCents ?? null,
      maxRedemptions: data.maxRedemptions ?? null,
      expiresAt,
      note: data.note ?? null,
    },
  });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.coupon_create", detail: code },
  });
  revalidatePath("/admin/coupons");
  return { ok: true };
}

