"use server";

import { randomInt } from "crypto";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";

/** Alphabet for generated gift codes — no ambiguous chars (0/O, 1/I). */
const ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

function randomSegment(len: number): string {
  let s = "";
  for (let i = 0; i < len; i++) s += ALPHABET[randomInt(ALPHABET.length)];
  return s;
}

/** Generate a code like `NXEON-XXXX-XXXX`. */
function generateGiftCode(): string {
  return `NXEON-${randomSegment(4)}-${randomSegment(4)}`;
}

/** Allocate a code that is unique in the DB (retry on the rare clash). */
async function uniqueGiftCode(): Promise<string> {
  for (let i = 0; i < 8; i++) {
    const code = generateGiftCode();
    const clash = await db.giftCode.findUnique({ where: { code } });
    if (!clash) return code;
  }
  // Extremely unlikely; add a third segment for extra entropy.
  return `${generateGiftCode()}-${randomSegment(4)}`;
}

// ---------- Admin: create ----------

const createSchema = z.object({
  amount: z.coerce.number().positive().max(10000),
  note: z.string().max(200).optional(),
  count: z.coerce.number().int().min(1).max(100),
});

/**
 * Create one or more gift/credit codes. `amount` is dollars (converted to
 * cents), `count` bulk-generates N codes with the same amount/note.
 */
export async function adminCreateGiftCodes(
  prev: any,
  formData: FormData
): Promise<{ error?: string; ok?: boolean; codes?: string[] }> {
  const admin = await requireArea("billing");
  const rawNote = String(formData.get("note") ?? "").trim();
  const parsed = createSchema.safeParse({
    amount: formData.get("amount"),
    note: rawNote === "" ? undefined : rawNote,
    count: formData.get("count") || 1,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid gift code details." };
  }
  const { amount, note, count } = parsed.data;
  const amountCents = Math.round(amount * 100);
  if (amountCents < 1) return { error: "Amount must be at least $0.01." };

  const codes: string[] = [];
  for (let i = 0; i < count; i++) {
    const code = await uniqueGiftCode();
    await db.giftCode.create({
      data: { code, amountCents, note: note ?? null },
    });
    codes.push(code);
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: "admin.giftcode_create",
      detail: `${count} x $${amount.toFixed(2)}`,
    },
  });
  revalidatePath("/admin/gift-codes");
  return { ok: true, codes };
}

// ---------- Admin: delete (unredeemed only) ----------

export async function adminDeleteGiftCode(id: string): Promise<void> {
  const admin = await requireArea("billing");
  const gift = await db.giftCode.findUnique({ where: { id } });
  if (!gift) return;
  if (gift.redeemedById) return; // never delete a redeemed code
  await db.giftCode.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.giftcode_delete", detail: gift.code },
  });
  revalidatePath("/admin/gift-codes");
}

// ---------- Customer: redeem ----------

/**
 * Redeem a gift code into the current user's wallet. Race-safe: the claim is an
 * `updateMany` guarded by `redeemedById: null` inside a transaction, so two
 * concurrent redemptions of the same code can only ever succeed once.
 */
export async function redeemGiftCode(
  rawCode: string
): Promise<{ ok?: boolean; error?: string; amountCents?: number }> {
  const user = await requireUser();
  const code = String(rawCode ?? "").trim().toUpperCase();
  if (!code) return { error: "Enter a gift code." };

  const gift = await db.giftCode.findUnique({ where: { code } });
  if (!gift) return { error: "That code isn't valid. Check for typos and try again." };
  if (gift.redeemedById) return { error: "This code has already been redeemed." };

  const result = await db.$transaction(async (tx) => {
    // Atomic claim: only succeeds if the code is still unredeemed.
    const claim = await tx.giftCode.updateMany({
      where: { id: gift.id, redeemedById: null },
      data: { redeemedById: user.id, redeemedAt: new Date() },
    });
    if (claim.count !== 1) return { error: "This code has already been redeemed." };

    await tx.user.update({
      where: { id: user.id },
      data: { balanceCents: { increment: gift.amountCents } },
    });
    await tx.walletTransaction.create({
      data: {
        userId: user.id,
        amountCents: gift.amountCents,
        description: `Gift code redeemed (${gift.code})`,
      },
    });
    return { ok: true, amountCents: gift.amountCents };
  });

  if (result.ok) {
    revalidatePath("/dashboard/billing");
  }
  return result;
}

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";

const schema = z.object({
  enabled: z.boolean(),
  threshold: z.coerce.number().min(0).max(10000),
  amount: z.coerce.number().min(0).max(10000),
});

/**
 * Persist wallet auto-recharge preferences for the current user. Dollar inputs
 * are converted to integer cents. When enabled, both a positive threshold and a
 * positive top-up amount are required. This only stores preferences — the actual
 * off-session Stripe charge is wired by the orchestrator.
 */
export async function saveAutoRecharge(
  prev: any,
  formData: FormData
): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  const parsed = schema.safeParse({
    enabled: formData.get("enabled") === "on",
    threshold: formData.get("threshold") || 0,
    amount: formData.get("amount") || 0,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Invalid auto-recharge settings." };
  }
  const { enabled, threshold, amount } = parsed.data;

  const thresholdCents = Math.round(threshold * 100);
  const amountCents = Math.round(amount * 100);

  if (enabled) {
    if (amountCents < 500) {
      return { error: "Recharge amount must be at least $5.00 when auto-recharge is on." };
    }
    if (thresholdCents < 0) {
      return { error: "Threshold can't be negative." };
    }
  }

  await db.user.update({
    where: { id: user.id },
    data: {
      autoRechargeEnabled: enabled,
      autoRechargeThresholdCents: enabled ? thresholdCents : null,
      autoRechargeAmountCents: enabled ? amountCents : null,
    },
  });

  revalidatePath("/dashboard/billing");
  return { ok: true };
}

"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import { adminCreateGiftCodes, adminDeleteGiftCode } from "@/lib/actions-gift";

export function GiftCodeCreateForm() {
  const [state, action, pending] = useActionState(
    adminCreateGiftCodes,
    {} as { error?: string; ok?: boolean; codes?: string[] }
  );
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state?.ok) formRef.current?.reset();
  }, [state]);

  const copyAll = () => {
    if (state?.codes?.length) {
      void navigator.clipboard?.writeText(state.codes.join("\n"));
    }
  };

  return (
    <form ref={formRef} action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {state?.error && (
        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      {state?.ok && state.codes && (
        <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-3 text-sm text-emerald-300">
          <div className="mb-2 flex items-center justify-between gap-3">
            <span>
              Created {state.codes.length} code{state.codes.length === 1 ? "" : "s"}.
            </span>
            <button type="button" onClick={copyAll} className="btn-ghost py-1 text-xs">
              Copy all
            </button>
          </div>
          <div className="flex flex-wrap gap-2">
            {state.codes.map((c) => (
              <span key={c} className="rounded bg-black/20 px-2 py-1 font-mono text-xs text-emerald-200">
                {c}
              </span>
            ))}
          </div>
        </div>
      )}
      <div>
        <label className="label">Amount (USD)</label>
        <input
          className="input"
          name="amount"
          type="number"
          min={0.01}
          step="0.01"
          placeholder="25.00"
          required
        />
      </div>
      <div>
        <label className="label">How many</label>
        <input className="input" name="count" type="number" min={1} max={100} defaultValue={1} />
        <p className="mt-1 text-[11px] text-slate-500">Bulk-generate up to 100</p>
      </div>
      <div className="sm:col-span-2">
        <label className="label">Note</label>
        <input className="input" name="note" placeholder="internal note (optional)" maxLength={200} />
      </div>
      <div className="col-span-full">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Generating…" : "Generate codes"}
        </button>
      </div>
    </form>
  );
}

export function DeleteGiftCodeButton({ id, code }: { id: string; code: string }) {
  const [pending, start] = useTransition();
  return (
    <button
      className="btn-danger py-1 text-xs"
      disabled={pending}
      onClick={() => {
        if (confirm(`Delete unredeemed gift code ${code}?`)) {
          start(() => adminDeleteGiftCode(id));
        }
      }}
    >
      Delete
    </button>
  );
}

export function CopyCodeButton({ code }: { code: string }) {
  const [copied, setCopied] = useState(false);
  return (
    <button
      type="button"
      className="btn-ghost py-1 text-xs"
      onClick={() => {
        void navigator.clipboard?.writeText(code);
        setCopied(true);
        setTimeout(() => setCopied(false), 1500);
      }}
    >
      {copied ? "Copied" : "Copy"}
    </button>
  );
}

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import {
  GiftCodeCreateForm,
  DeleteGiftCodeButton,
  CopyCodeButton,
} from "@/components/admin/GiftCodeControls";

export const dynamic = "force-dynamic";

export default async function AdminGiftCodes() {
  await requireArea("billing");
  const codes = await db.giftCode.findMany({
    orderBy: { createdAt: "desc" },
    include: { redeemedBy: { select: { email: true, name: true } } },
    take: 500,
  });

  const redeemedCount = codes.filter((c) => c.redeemedById !== null).length;
  const outstandingCents = codes
    .filter((c) => c.redeemedById === null)
    .reduce((sum, c) => sum + c.amountCents, 0);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Gift & credit codes"
        sub="Generate prepaid wallet-credit codes for customers to redeem."
      />

      <div className="grid gap-4 sm:grid-cols-3">
        <div className="card">
          <p className="section-label mb-1">Total codes</p>
          <p className="text-2xl font-bold">{codes.length}</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Redeemed</p>
          <p className="text-2xl font-bold">{redeemedCount}</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Outstanding value</p>
          <p className="text-2xl font-bold">{fmtMoney(outstandingCents)}</p>
        </div>
      </div>

      <div className="card">
        <p className="section-label mb-4">Generate codes</p>
        <GiftCodeCreateForm />
      </div>

      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">All codes</p>
        {codes.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">
            No codes yet — generate some above.
          </p>
        ) : (
          <table className="table-shell mt-2 min-w-[820px]">
            <thead>
              <tr>
                <th>Code</th>
                <th className="text-right">Amount</th>
                <th>Note</th>
                <th>Status</th>
                <th>Redeemed by</th>
                <th>Created</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {codes.map((c) => {
                const redeemed = c.redeemedById !== null;
                return (
                  <tr key={c.id}>
                    <td className="font-mono text-sm">{c.code}</td>
                    <td className="text-right font-mono">{fmtMoney(c.amountCents)}</td>
                    <td className="max-w-xs truncate text-xs text-slate-400">{c.note ?? "—"}</td>
                    <td>
                      {redeemed ? (
                        <Badge tone="slate">redeemed</Badge>
                      ) : (
                        <Badge tone="green">available</Badge>
                      )}
                    </td>
                    <td className="text-xs text-slate-400">
                      {redeemed ? (
                        <span title={c.redeemedAt?.toISOString()}>
                          {c.redeemedBy?.email ?? c.redeemedBy?.name ?? "unknown"}
                          {c.redeemedAt && (
                            <span className="ml-1 text-slate-500">· {timeAgo(c.redeemedAt)}</span>
                          )}
                        </span>
                      ) : (
                        "—"
                      )}
                    </td>
                    <td className="text-xs text-slate-400" title={c.createdAt.toISOString()}>
                      {timeAgo(c.createdAt)}
                    </td>
                    <td className="text-right">
                      <div className="flex items-center justify-end gap-1">
                        {!redeemed && <CopyCodeButton code={c.code} />}
                        {!redeemed && <DeleteGiftCodeButton id={c.id} code={c.code} />}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import { redeemGiftCode } from "@/lib/actions-gift";
import { fmtMoney } from "@/components/ui/primitives";

export function RedeemGift() {
  const [code, setCode] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<{ amountCents: number } | null>(null);
  const [pending, start] = useTransition();

  const redeem = () => {
    setError(null);
    setSuccess(null);
    const trimmed = code.trim();
    if (!trimmed) {
      setError("Enter a gift code.");
      return;
    }
    start(async () => {
      const res = await redeemGiftCode(trimmed);
      if (res.ok) {
        setSuccess({ amountCents: res.amountCents ?? 0 });
        setCode("");
      } else {
        setError(res.error ?? "Couldn't redeem that code.");
      }
    });
  };

  return (
    <div>
      <div className="flex flex-wrap items-end gap-2">
        <div className="flex-1">
          <label className="label">Gift or credit code</label>
          <input
            className="input w-full font-mono uppercase"
            value={code}
            onChange={(e) => {
              setCode(e.target.value);
              if (error) setError(null);
            }}
            placeholder="NXEON-XXXX-XXXX"
            maxLength={32}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                redeem();
              }
            }}
          />
        </div>
        <button type="button" className="btn-primary" onClick={redeem} disabled={pending}>
          {pending ? "Redeeming…" : "Redeem"}
        </button>
      </div>
      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
      {success && (
        <p className="mt-2 text-sm text-emerald-300">
          Success — {fmtMoney(success.amountCents)} added to your wallet.
        </p>
      )}
      {!error && !success && (
        <p className="mt-2 text-xs text-slate-500">
          Redeem a prepaid code to add credit to your wallet balance.
        </p>
      )}
    </div>
  );
}

"use client";

import { useActionState, useState } from "react";
import { saveAutoRecharge } from "@/lib/actions-billing-prefs";

export function AutoRecharge({
  enabled: initialEnabled,
  thresholdCents,
  amountCents,
}: {
  enabled: boolean;
  thresholdCents: number | null;
  amountCents: number | null;
}) {
  const [state, action, pending] = useActionState(
    saveAutoRecharge,
    {} as { ok?: boolean; error?: string }
  );
  const [enabled, setEnabled] = useState(initialEnabled);

  const toDollars = (c: number | null, fallback: string) =>
    c !== null ? (c / 100).toFixed(2) : fallback;

  return (
    <form action={action} className="space-y-4">
      <label className="flex items-center gap-3 text-sm">
        <input
          type="checkbox"
          name="enabled"
          checked={enabled}
          onChange={(e) => setEnabled(e.target.checked)}
        />
        <span className="font-medium">Automatically top up my wallet</span>
      </label>

      <div className={`grid gap-3 sm:grid-cols-2 ${enabled ? "" : "pointer-events-none opacity-50"}`}>
        <div>
          <label className="label">When balance drops below (USD)</label>
          <input
            className="input"
            name="threshold"
            type="number"
            min={0}
            step="0.01"
            defaultValue={toDollars(thresholdCents, "5.00")}
            disabled={!enabled}
          />
        </div>
        <div>
          <label className="label">Top up by (USD)</label>
          <input
            className="input"
            name="amount"
            type="number"
            min={5}
            step="0.01"
            defaultValue={toDollars(amountCents, "25.00")}
            disabled={!enabled}
          />
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Saving…" : "Save preferences"}
        </button>
        {state?.error && <span className="text-sm text-red-400">{state.error}</span>}
        {state?.ok && <span className="text-sm text-emerald-300">Preferences saved.</span>}
      </div>

      <p className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
        Requires a saved card — charging is handled automatically once a payment method is on file.
      </p>
    </form>
  );
}

